/**
 * Precompiled Ajv validators per vendored UCP version (generated by scripts/compile-validators.ts,
 * because Workers cannot compile schemas at runtime). Loaded once at module init.
 */
import * as v20260408 from './generated/validators-2026-04-08.js';
import * as v20260825 from './generated/validators-2026-08-25.js';
import type { AjvError, GeneratedValidator } from './validatorTypes';
import { LATEST_VERSION, isVendored, type VendoredVersion } from './versions';

export type ValidatorName = 'profile' | 'catalogSearchResponse' | 'checkout';

const BY_VERSION: Record<VendoredVersion, Record<ValidatorName, GeneratedValidator>> = {
  '2026-04-08': v20260408,
  '2026-08-25': v20260825,
};

/** The vendored version used to validate a document that declares `declared`. */
export function validationVersion(declared: unknown): VendoredVersion {
  return typeof declared === 'string' && isVendored(declared) ? declared : LATEST_VERSION;
}

export interface ValidationOutcome {
  valid: boolean;
  version: VendoredVersion;
  errors: AjvError[];
}

export function validate(name: ValidatorName, data: unknown, version: VendoredVersion): ValidationOutcome {
  const fn = BY_VERSION[version][name];
  const valid = fn(data);
  return { valid, version, errors: valid ? [] : dedupeErrors(fn.errors ?? []) };
}

/**
 * Ajv with allErrors reports every failing branch of anyOf/oneOf. Collapse duplicates and drop
 * the generic "must match a schema in anyOf" noise when more specific errors exist.
 */
function dedupeErrors(errors: AjvError[]): AjvError[] {
  const seen = new Set<string>();
  const specific = errors.filter((e) => !['anyOf', 'oneOf', 'if', 'allOf'].includes(e.keyword));
  const list = specific.length ? specific : errors;
  return list.filter((e) => {
    const key = `${e.instancePath}|${e.message}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function formatAjvError(e: AjvError): string {
  const path = e.instancePath || '(root)';
  let msg = e.message ?? e.keyword;
  if (e.keyword === 'additionalProperties' && e.params?.additionalProperty) msg += `: ${String(e.params.additionalProperty)}`;
  if (e.keyword === 'enum' && Array.isArray(e.params?.allowedValues)) msg += `: ${(e.params.allowedValues as unknown[]).join(', ')}`;
  return `${path} ${msg}`;
}
